import torch
import torch.nn as nn


class ModelNew(nn.Module):
    """Fused: out = (x @ W^T + b) * (1 + scaling_factor).

    The reference computes y = x@W^T + b, then y*s + y = y*(1+s).
    We fold (1+s) into the weights so the forward pass is a single addmm.
    """

    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor

    def forward(self, x):
        scale = 1.0 + self.scaling_factor
        return torch.addmm(
            self.matmul.bias * scale,
            x,
            self.matmul.weight.t() * scale,
        )
EOF
